mapper.select:
SELECT us.school_id AS schoolId, us.college_id AS collegeId, us.major_id AS majorId, m3.code AS majorCode, m3.name AS majorName, latest.id AS adjustmentId, latest.create_time AS updateTime, latest.year AS year, latest.study_mode AS studyMode, CASE WHEN IFNULL(latest.create_time, '1970-01-01 00:00:00') > COALESCE(us.last_read_time, us.create_time) THEN 1 ELSE 0 END AS hasUpdate FROM biz_user_subscription us LEFT JOIN biz_school s ON s.id = us.school_id LEFT JOIN biz_major m3 ON m3.id = us.major_id LEFT JOIN biz_major m2 ON m2.code = m3.parent_code AND m2.level = 2 LEFT JOIN biz_major m1 ON m1.code = m2.parent_code AND m1.level = 1 LEFT JOIN ( SELECT a.id, a.school_id, a.college_id, a.major_id, a.year, a.study_mode, a.create_time FROM biz_adjustment a INNER JOIN ( SELECT k.school_id, k.college_id, k.major_id, MAX(CONCAT(DATE_FORMAT(a2.create_time, '%Y%m%d%H%i%s'), '-', LPAD(a2.id, 20, '0'))) AS latest_key FROM ( SELECT us2.school_id, us2.college_id, us2.major_id FROM biz_user_subscription us2 WHERE us2.user_id = #{userId} AND us2.school_id IN
#{schoolId}
) k LEFT JOIN biz_adjustment a2 ON a2.school_id = k.school_id AND a2.college_id = k.college_id AND a2.major_id = k.major_id GROUP BY k.school_id, k.college_id, k.major_id ) latest_key ON latest_key.school_id = a.school_id AND latest_key.college_id = a.college_id AND latest_key.major_id = a.major_id AND CONCAT(DATE_FORMAT(a.create_time, '%Y%m%d%H%i%s'), '-', LPAD(a.id, 20, '0')) = latest_key.latest_key ) latest ON latest.school_id = us.school_id AND latest.college_id = us.college_id AND latest.major_id = us.major_id
us.user_id = #{userId} AND us.school_id IN
#{schoolId}
AND s.province_code = #{reqVO.provinceCode}
AND m1.id = #{reqVO.majorLevel1Id}
AND () = #{reqVO.schoolLevel}
AND latest.create_time >= DATE_SUB(NOW(), INTERVAL #{reqVO.updateDays} DAY)
ORDER BY updateTime DESC
